import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());long[] a = new long[n + 1];long[] prefixSum = new long[n + 1];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 1; i <= n; i++) {a[i] = Long.parseLong(st.nextToken());prefixSum[i] = prefixSum[i - 1] + a[i];}long maxSpecialSum = Long.MIN_VALUE;for (int i = 1; i <= n; i++) {int k = 1;int remaining = n - i + 1;while ((k * (k + 1)) / 2 <= remaining) {k++;}k--;int end = i + (k * (k + 1)) / 2 - 1;long currentSum = prefixSum[end] - prefixSum[i - 1];if (currentSum > maxSpecialSum) {maxSpecialSum = currentSum;}}System.out.println(maxSpecialSum);}}